root=Path(os.environ.get('MARKETING_OUTPUT_DIR',Path(__file__).parent.parent/'outputs'/'marketing'))
site=root/'website'
site.mkdir(parents=True,exist_ok=True)
def write(path,content):
 p=site/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content,encoding='utf-8')

def nav(active=''):
 return '''<a class="skip" href="#main">Skip to content</a><header class="header"><a class="wordmark" href="/" aria-label="KAThu on marketing home">KAThu<span>on marketing</span></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu</button><nav id="navigation" aria-label="Main navigation"><a href="/#work">Work</a><a href="/#approach">Approach</a><a href="/#about">About</a><a href="/#experience">Experience</a><a class="nav-contact" href="/#contact">Let’s talk</a></nav></header>'''

def footer():
 return f'''<footer class="footer"><a class="wordmark" href="/">KAThu<span>on marketing</span></a><p>Phan Hoai Thu · Ho Chi Minh City</p><div><a href="{P['linkedin']}">LinkedIn</a><a href="https://kathuatwork.com/">Data portfolio</a><a href="mailto:{P['email']}">Email</a></div><small>© 2026 Phan Hoai Thu</small></footer>'''

def page(title,desc,body,path='/'):
 return f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#5936c9"><title>{e(title)} | KAThu on marketing</title><meta name="description" content="{e(desc,quote=True)}"><link rel="canonical" href="{P['site']}{path}"><meta property="og:title" content="{e(title,quote=True)}"><meta property="og:description" content="{e(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{P['site']}{path}"><meta name="twitter:card" content="summary"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css"><script src="/app.js" defer></script></head><body>{nav()}<main id="main">{body}</main>{footer()}</body></html>'''

def card(c,feature=False):
 img=f'<img src="/assets/{c["images"][0][0]}" alt="{e(c["images"][0][1])}" loading="lazy" width="1000" height="562">' if c['images'] else '<div class="text-art"><span>Acquisition</span><span>Activation</span><span>Retention</span><span>Value</span></div>'
 return f'''<article class="work-card {'featured-card' if feature else ''}" data-category="{e(c['category'])}"><a class="card-image" href="/work/{c['slug']}/" tabindex="-1" aria-hidden="true">{img}</a><div class="card-body"><div class="card-meta"><span>{e(c['client'])}</span><span>{e(c['kind'])}</span></div><h3><a href="/work/{c['slug']}/">{e(c['title'])}</a></h3><p>{e(c['intro'])}</p><div class="card-result"><strong>{e(c['metric'])}</strong><span>{e(c['metric_label'])}</span></div><a class="text-link" href="/work/{c['slug']}/">Read case study<span class="sr-only">: {e(c['client'])}</span></a></div></article>'''

featured=''.join(card(CASES[i],True) for i in [0,1,3])
library=''.join(card(c) for c in CASES)
