filters=''.join(f'<button type="button" class="filter {"active" if i==0 else ""}" aria-pressed="{"true" if i==0 else "false"}" data-filter="{e(v)}">{e(v)}</button>' for i,v in enumerate(categories))
exp=''.join(f'<article class="experience-row"><p class="date">{x["dates"]}</p><div><h3>{x["company"]}</h3><p class="role">{x["role"]}</p><p>{e(x["bullets"][0])}</p></div></article>' for x in EXPERIENCE)
home=f'''
<section class="hero wrap"><div class="hero-copy"><p class="intro-label">Phan Hoai Thu (Katherine)</p><h1>A marketer who follows the whole journey.</h1><p class="hero-lede">I build campaigns, grow search visibility and improve the path to conversion. Data helps me understand what people need—and where to go next.</p><div class="hero-actions"><a class="button primary" href="#work">Explore my work</a><a class="button secondary" href="/documents/Phan_Hoai_Thu_Digital_Marketing_CV.pdf" download>Download CV</a></div><p class="hero-location">Digital marketing & growth · Ho Chi Minh City</p></div><div class="hero-visual"><div class="portrait-frame"><img src="/assets/katherine-ava.png" alt="Phan Hoai Thu" fetchpriority="high" width="850" height="1100"></div><div class="hero-note"><span>My starting point</span><p>What will move<br>the customer forward?</p></div></div></section>
<div class="brand-band"><div class="wrap"><p>Marketing across different customer journeys</p><div><span>B2B technology</span><span>Education</span><span>SaaS</span><span>E-commerce</span></div></div></div>
<section class="section wrap" aria-labelledby="selected-heading"><div class="section-heading"><div><p class="section-kicker">Selected campaign work</p><h2 id="selected-heading">The strategy.<br>The work. The results.</h2></div><p>From choosing a channel to improving the next click, these projects show how I connect execution with measurement.</p></div><div class="featured-grid">{featured}</div></section>
<section class="approach section" id="approach"><div class="wrap approach-grid"><div><p class="section-kicker">How I work</p><h2>Start with a customer.<br>Make a clear decision.</h2><p>A strong campaign brings audience understanding, creative execution and useful measurement into the same conversation.</p></div><div class="approach-steps"><article><span>01</span><div><h3>Understand the audience</h3><p>Research the market, search intent and customer journey. Decide which problem the campaign should solve.</p></div></article><article><span>02</span><div><h3>Build the path</h3><p>Connect the message, channel, content and landing page. Work closely with creative, product and sales.</p></div></article><article><span>03</span><div><h3>Measure, learn, improve</h3><p>Check tracking, review conversion and lead quality, and turn the next question into a useful test.</p></div></article></div></div></section>
<section class="section wrap" id="work"><div class="section-heading"><div><p class="section-kicker">The complete portfolio</p><h2>Campaigns and the thinking behind them.</h2></div><p>Professional work comes first. Independent projects extend the story into retention, promotions, targeting and experimentation.</p></div><div class="filters" role="group" aria-label="Filter case studies">{filters}</div><p class="result-count" aria-live="polite">13 case studies</p><div class="work-grid">{library}</div></section>
<section class="about section" id="about"><div class="wrap about-grid"><div><p class="section-kicker">A little about me</p><h2>Marketing is my craft.<br>Analysis sharpens it.</h2><p>I’m Thu, also known as Katherine. My experience spans paid campaigns, organic growth and customer journeys across international technology brands and e-commerce.</p><p>I enjoy the full process: understanding a market, shaping a plan with the team, getting the work live and asking whether it changed the right behavior.</p><p>SQL, dashboards and experiments give me a deeper view of that last question. The work still starts with a marketing decision.</p><a class="text-link" href="{P['linkedin']}">Meet me on LinkedIn</a></div><div class="capabilities"><h3>What I bring</h3><dl><dt>Acquire</dt><dd>Google Ads, Meta Ads, SEO, keyword and audience research, content planning</dd><dt>Convert</dt><dd>Landing-page strategy, customer journeys, CRO, creative testing, CRM lead insight</dd><dt>Understand</dt><dd>GA4, GTM, Looker Studio, Excel, SQL, Power BI, customer segmentation</dd><dt>Deliver</dt><dd>Cross-functional coordination, team coaching, reporting, CMS and workflow planning</dd></dl><div class="education"><strong>Bachelor of Business Administration</strong><span>University of Economics Ho Chi Minh City · 2018–2022</span><span>TheHau Data Analytics Mentoring Program · 2025</span><span>IELTS overall 7.5 · 2022</span></div></div></div></section>
<section class="section wrap" id="experience"><div class="section-heading"><div><p class="section-kicker">Experience</p><h2>Built through real work.</h2></div><a class="button secondary" href="/documents/Phan_Hoai_Thu_Digital_Marketing_CV.pdf" download>Download full CV</a></div>{exp}<article class="experience-row"><p class="date">2026</p><div><h3>Independent growth and analytics projects</h3><p>Experiment interpretation, campaign targeting, customer segmentation, promotion review and retention strategy. Each project is labeled with its evidence and limitations.</p></div></article></section>
<section class="contact" id="contact"><div class="wrap"><p class="section-kicker">Let’s talk</p><h2>Bring me a marketing<br>problem worth solving.</h2><a class="email-link" href="mailto:{P['email']}">{P['email']}</a><div class="contact-links"><a href="{P['linkedin']}">LinkedIn</a><a href="tel:+84817375930">+84 817 375 930</a><a href="/documents/Phan_Hoai_Thu_Digital_Marketing_CV.pdf" download>Download CV</a></div></div></section>'''
write('index.html',page('Phan Hoai Thu | Digital marketing & growth',P['summary'],home))

for c in CASES:
 actions=''.join(f'<li>{e(a)}</li>' for a in c['actions'])
 findings=''.join(f'<article><h3>{e(t)}</h3><p>{e(s)}</p></article>' for t,s in c['findings'])
 pics=''.join(f'<figure><a href="/assets/{name}" target="_blank" rel="noopener"><img src="/assets/{name}" alt="{e(cap)}" loading="lazy" width="1200" height="675"></a><figcaption>{e(cap)}. Open image for a closer view.</figcaption></figure>' for name,cap in c['images'])
 sources=''.join(f'<li><a href="{e(url,quote=True)}">{e(label)}</a></li>' if url.startswith('https://') else f'<li>{e(label)}: {e(url)}</li>' for label,url in c['sources'])
 related=[x for x in CASES if x['slug']!=c['slug'] and x['category']==c['category']][:2]
 if len(related)<2:related+=[x for x in CASES if x['slug']!=c['slug'] and x not in related][:2-len(related)]
 rel=''.join(f'<a href="/work/{x["slug"]}/"><span>{e(x["client"])}</span><h3>{e(x["title"])}</h3></a>' for x in related)
 body=f'''<section class="case-hero wrap"><a class="back-link" href="/#work">Back to all work</a><div class="case-labels"><span>{e(c['client'])}</span><span>{e(c['kind'])}</span><span>{e(c['category'])}</span></div><h1>{e(c['title'])}</h1><p class="case-intro">{e(c['intro'])}</p><div class="case-result"><strong>{e(c['metric'])}</strong><span>{e(c['metric_label'])}</span></div><div class="tool-list">{''.join(f'<span>{e(t)}</span>' for t in c['tools'])}</div></section><div class="case-layout wrap"><aside class="case-nav" aria-label="Case study sections"><a href="#challenge">The challenge</a><a href="#work-done">What I did</a><a href="#findings">What I learned</a><a href="#decision">Marketing decision</a><a href="#evidence">Project evidence</a><a href="#context">Context & sources</a></aside><div class="case-content"><section id="challenge"><h2>The challenge</h2><p>{e(c['challenge'])}</p></section><section id="work-done"><h2>What I did</h2><ul class="actions-list">{actions}</ul></section><section id="findings"><h2>What the work showed</h2><div class="finding-list">{findings}</div></section><section id="decision" class="decision"><p class="section-kicker">The marketing decision</p><h2>Where this leads</h2><p>{e(c['decision'])}</p></section><section id="evidence"><h2>Project evidence</h2>{pics if pics else '<p>This public summary preserves the approach and recommendations. Confidential business figures and source materials are kept out of this page.</p>'}</section><section id="context" class="source-context"><h2>Context and sources</h2><p>{e(c['limits'])}</p><ul>{sources}</ul></section></div></div><section class="section wrap"><h2>Continue exploring</h2><div class="related">{rel}</div></section>'''
 write(f'work/{c["slug"]}/index.html',page(c['title'],c['intro'],body,f'/work/{c["slug"]}/'))

write('404.html',page('Page not found','Find Phan Hoai Thu’s marketing portfolio.','<section class="section wrap"><h1>This page has moved.</h1><p>Explore the full portfolio to find the case study you need.</p><a class="button primary" href="/#work">Go to the portfolio</a></section>'))
write('robots.txt',f'User-agent: *\nAllow: /\nSitemap: {P["site"]}/sitemap.xml\n')
