write('favicon.svg','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="16" fill="#5936c9"/><text x="32" y="45" text-anchor="middle" font-family="Arial,sans-serif" font-size="42" font-weight="700" fill="#ffd749">K</text></svg>')
write('vercel.json',json.dumps({'version':2,'cleanUrls':True,'trailingSlash':True,'headers':[{'source':'/(.*)','headers':[{'key':'X-Content-Type-Options','value':'nosniff'},{'key':'Referrer-Policy','value':'strict-origin-when-cross-origin'},{'key':'X-Frame-Options','value':'SAMEORIGIN'}]}]},indent=2))
write('.vercelignore','.git\n.vercel\nnode_modules\n')
write('package.json',json.dumps({'name':'kathuonmkt','private':True,'version':'1.0.0','description':'Phan Hoai Thu marketing portfolio','scripts':{'dev':'python -m http.server 4173','deploy':'vercel --prod'},'engines':{'node':'24.x'}},indent=2))
(root/'content.json').write_text(json.dumps({'profile':P,'experience':EXPERIENCE,'cases':CASES},ensure_ascii=False,indent=2),encoding='utf-8')
